// The demo photos as data URLs, loaded only when the page is opened from disk (file://).
// Browsers treat every file:// image as cross-origin and block exporting a canvas that
// drew one; data URLs are not cross-origin, so the in-browser image tools keep working.
window.METAMORPH = window.METAMORPH || {};
window.METAMORPH.LOCAL_IMAGES = {"assets/img/vacation.jpg": "data:image/jpeg;base64,", "assets/img/skyline.jpg": "data:image/jpeg;base64,"};
